+        if (dep.symbols.isCleared) {
+          dep.symbols.ensure();
+          dep.symbols.set('*', `${dep.id}$`);
+        }
+      }
+
+      if (needs_esm_helpers) {
+        asset.addDependency({
+          specifier: '@parcel/transformer-js/src/esmodule-helpers.js',
+          specifierType: 'esm',
+          resolveFrom: __filename,
+          env: {
+            includeNodeModules: {
+              '@parcel/transformer-js': true,
+            },
+          },
+        });
+      }
+    }
