+    asset.type = 'js';
+    asset.setBuffer(compiledCode);
+
+    if (map) {
+      let sourceMap = new SourceMap(options.projectRoot);
+      sourceMap.addVLQMap(JSON.parse(map));
+      if (originalMap) {
+        sourceMap.extends(originalMap);
+      }
+      asset.setMap(sourceMap);
+    }
+
+    return [asset, ...macroAssets];
+  },
+}): Transformer);
