+pub enum JsValue {
+  Undefined,
+  Null,
+  Bool(bool),
+  Number(f64),
+  String(String),
+  Regex { source: String, flags: String },
+  Array(Vec<JsValue>),
+  Object(IndexMap<String, JsValue>),
+  Function(String),
+}
